package dev.pro8.homeview.direct;

import android.content.Context;
import android.net.Uri;
import android.util.AtomicFile;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;

/** HA OAuth + a small whitelisted REST surface. Tokens never leave app-private storage. */
final class HomeAssistantClient {
    static final String CLIENT="http://127.0.0.1:8806/frame/hv/", CALLBACK="http://127.0.0.1:8806/ha/callback";
    private final Context context;private final AtomicFile file;private JSONObject account=new JSONObject();private String nonce,verifier;private long pendingAt;private final Map<String,String> lastClimateModes=new HashMap<>();
    HomeAssistantClient(Context c){context=c.getApplicationContext();file=new AtomicFile(new File(c.getFilesDir(),"ha-account.json"));try(InputStream in=file.openRead()){account=new JSONObject(new String(NetEaseClient.read(in,128*1024),"UTF-8"));}catch(Exception ignored){}}
    String base(){String raw=context.getSharedPreferences("homeview_pro8",0).getString("ha_url",account.optString("base",HomeActivity.DEFAULT_HA)).trim();if(raw.isEmpty())return "";try{URL u=new URL(raw);if(!u.getProtocol().equals("http")&&!u.getProtocol().equals("https"))return "";return u.getProtocol()+"://"+u.getAuthority();}catch(Exception e){return "";}}
    private void save()throws Exception{FileOutputStream out=null;try{out=file.startWrite();out.write(account.toString().getBytes("UTF-8"));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
    private boolean authorized(){return !base().isEmpty()&&base().equals(account.optString("base"))&&!account.optString("refresh").isEmpty();}
    synchronized JSONObject status()throws Exception{return NetEaseClient.obj("ok",true,"configured",!base().isEmpty(),"authorized",authorized(),"url",base(),"home_name",homeName(),"pins",account.optJSONObject("pins")==null?new JSONObject():account.optJSONObject("pins"));}
    private String homeName(){return context.getSharedPreferences("homeview_pro8",0).getString("home_name","我的家");}
    synchronized JSONObject rename(JSONObject b)throws Exception{String name=b.optString("home_name","").trim();if(name.isEmpty()||name.codePointCount(0,name.length())>24)throw new IllegalArgumentException("家庭名称请输入 1–24 个字");for(int i=0;i<name.length();i++)if(Character.isISOControl(name.charAt(i)))throw new IllegalArgumentException("家庭名称不能包含换行或控制字符");if(!context.getSharedPreferences("homeview_pro8",0).edit().putString("home_name",name).commit())throw new IOException("名称保存失败，请重试");return NetEaseClient.obj("ok",true,"home_name",name);}
    private String form(JSONObject d)throws Exception{StringBuilder b=new StringBuilder();Iterator<String> keys=d.keys();while(keys.hasNext()){String k=keys.next();if(b.length()>0)b.append('&');b.append(URLEncoder.encode(k,"UTF-8")).append('=').append(URLEncoder.encode(d.optString(k),"UTF-8"));}return b.toString();}
    private Object request(String path,JSONObject body,boolean auth,boolean form)throws Exception{
        return request(path,body,auth,form,5000);
    }
    private Object request(String path,JSONObject body,boolean auth,boolean form,int readTimeout)throws Exception{
        if(base().isEmpty())throw new IllegalArgumentException("请先设置 Home Assistant 地址");
        HttpURLConnection c=(HttpURLConnection)new URL(base()+path).openConnection();c.setConnectTimeout(2500);c.setReadTimeout(readTimeout);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");
        try{if(auth)c.setRequestProperty("Authorization","Bearer "+access());if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type",form?"application/x-www-form-urlencoded":"application/json");byte[] bytes=(form?form(body):body.toString()).getBytes("UTF-8");c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}
            int code=c.getResponseCode();if(code==401)throw new IllegalArgumentException("HA 授权已失效，请重新登录");if(code<200||code>=300)throw new IllegalArgumentException("HA 请求未成功，请稍后重试");byte[] data;try(InputStream in=c.getInputStream()){data=NetEaseClient.read(in,2*1024*1024);}return data.length==0?new JSONObject():new JSONTokener(new String(data,"UTF-8")).nextValue();
        }finally{c.disconnect();}
    }
    synchronized JSONObject login()throws Exception{if(base().isEmpty())throw new IllegalArgumentException("请先设置 HA 地址");byte[] b=new byte[48];new SecureRandom().nextBytes(b);verifier=Base64.encodeToString(b,Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP);nonce=UUID.randomUUID().toString();pendingAt=System.currentTimeMillis();String challenge=Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes("US-ASCII")),Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP);String url=base()+"/auth/authorize?"+form(NetEaseClient.obj("client_id",CLIENT,"redirect_uri",CALLBACK,"state",nonce,"code_challenge",challenge,"code_challenge_method","S256"));return NetEaseClient.obj("ok",true,"url",url);}
    synchronized void exchange(String code,String state)throws Exception{if(nonce==null||state==null||!MessageDigest.isEqual(nonce.getBytes("UTF-8"),state.getBytes("UTF-8"))||System.currentTimeMillis()-pendingAt>600000)throw new IllegalArgumentException("授权已过期，请重新登录");nonce=null;JSONObject t=(JSONObject)request("/auth/token",NetEaseClient.obj("grant_type","authorization_code","code",code,"client_id",CLIENT,"code_verifier",verifier),false,true);verifier=null;if(t.optString("refresh_token").isEmpty())throw new IllegalArgumentException("HA 未返回授权");account.put("base",base()).put("client",CLIENT).put("refresh",t.getString("refresh_token")).put("access",t.getString("access_token")).put("expires",System.currentTimeMillis()/1000+t.optInt("expires_in",1800)-30);save();}
    private synchronized String access()throws Exception{if(!authorized())throw new IllegalArgumentException("请先登录 Home Assistant");if(account.optLong("expires")<System.currentTimeMillis()/1000){JSONObject t=(JSONObject)request("/auth/token",NetEaseClient.obj("grant_type","refresh_token","refresh_token",account.getString("refresh"),"client_id",account.optString("client",CLIENT)),false,true);account.put("access",t.getString("access_token")).put("expires",System.currentTimeMillis()/1000+t.optInt("expires_in",1800)-30);save();}return account.getString("access");}
    synchronized JSONObject entities()throws Exception{JSONArray data=(JSONArray)request("/api/states",null,true,false),out=new JSONArray();Set<String> domains=new HashSet<>(Arrays.asList("light","switch","climate","fan","input_boolean","humidifier","scene","sensor"));String[] keys={"friendly_name","device_class","unit_of_measurement","brightness","verge_stored_brightness","verge_stored_kelvin","stored_color_temp_kelvin","stored_rgb_color","rgb_color","temperature","current_temperature","min_temp","max_temp","target_temp_step","hvac_modes","supported_features","supported_color_modes","color_mode","color_temp_kelvin","min_color_temp_kelvin","max_color_temp_kelvin","color_temp","min_mireds","max_mireds"};for(int i=0;i<data.length();i++){JSONObject x=data.getJSONObject(i);String id=x.optString("entity_id"),state=x.optString("state");if(!domains.contains(id.split("\\.")[0]))continue;JSONObject attributes=new JSONObject(),a=x.optJSONObject("attributes");if(a!=null)for(String k:keys)if(a.has(k))attributes.put(k,a.get(k));if(id.startsWith("climate.")&&!state.equals("off")&&!state.equals("unknown")&&!state.equals("unavailable"))lastClimateModes.put(id,state);out.put(NetEaseClient.obj("entity_id",id,"state",state,"attributes",attributes));}return NetEaseClient.obj("ok",true,"items",out,"pins",account.optJSONObject("pins")==null?new JSONObject():account.optJSONObject("pins"));}
    synchronized JSONObject pins(JSONObject b)throws Exception{JSONArray list=entities().getJSONArray("items");Set<String> ids=new HashSet<>();for(int i=0;i<list.length();i++)ids.add(list.getJSONObject(i).getString("entity_id"));JSONObject pins=new JSONObject();String[] names={"light","climate","temperature","humidity","home_scene","night_scene"};for(String name:names){String id=b.optString(name),domain=id.split("\\.")[0];boolean valid=(name.equals("light")||name.equals("climate"))?Arrays.asList("light","switch","climate","fan","input_boolean","humidifier").contains(domain):name.endsWith("scene")?domain.equals("scene"):domain.equals("sensor");if(!id.isEmpty()&&(!ids.contains(id)||!valid))throw new IllegalArgumentException("请选择有效的设备");if(!id.isEmpty()&&(name.equals("temperature")||name.equals("humidity"))){JSONObject attrs=null;for(int j=0;j<list.length();j++)if(id.equals(list.getJSONObject(j).optString("entity_id")))attrs=list.getJSONObject(j).optJSONObject("attributes");String unit=attrs==null?"":attrs.optString("unit_of_measurement"),friendly=attrs==null?"":attrs.optString("friendly_name").toLowerCase(Locale.ROOT);boolean sensor=attrs!=null&&attrs.optString("device_class").equals(name)||name.equals("temperature")&&(unit.equals("°C")||unit.equals("°F")||unit.equals("K"))||name.equals("humidity")&&unit.equals("%")&&(friendly.contains("humidity")||friendly.contains("湿度"));if(!sensor)throw new IllegalArgumentException("请选择对应的温湿度传感器");}pins.put(name,id);}account.put("pins",pins);save();return NetEaseClient.obj("ok",true,"pins",pins);}
    synchronized JSONObject control(JSONObject b)throws Exception{String id=b.optString("entity_id");JSONObject selected=null;JSONArray available=entities().getJSONArray("items");for(int i=0;i<available.length();i++)if(id.equals(available.getJSONObject(i).optString("entity_id")))selected=available.getJSONObject(i);if(selected==null)throw new IllegalArgumentException("请先选择要控制的设备");JSONObject plan=HAControl.plan(selected,b,lastClimateModes.get(id));JSONObject attrs=selected.optJSONObject("attributes");
        // A cold Verge Mesh connection can take several seconds before the lamp confirms.
        int readTimeout=5000;
        if(attrs!=null&&attrs.has("verge_stored_brightness"))readTimeout=60000;
        else if(attrs!=null&&attrs.has("stored_rgb_color"))readTimeout=40000;
        request("/api/services/"+plan.getString("domain")+"/"+plan.getString("service"),plan.getJSONObject("data"),true,false,readTimeout);return NetEaseClient.obj("ok",true);}
}
